		else if (c == ':')
			printf("opt=: arg=(null)\n");
		else
			printf("opt=%c arg=%s\n", c, optarg ? optarg : "(null)");
	}
	for (int i = optind; i < argc_; i++) {
		printf("REST:%s\n", argv_[i]);
	}
